import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"工具接口","link":"/api/SIMD-API/basic_api/tool_interface/tool_interface"},{"text":"执行模式","link":"/api/SIMD-API/basic_api/tool_interface/execution_mode/execution_mode"},{"text":"Async","link":"/api/SIMD-API/basic_api/tool_interface/execution_mode/Async"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/tool_interface/execution_mode/Async.md","filePath":"api/SIMD-API/basic_api/tool_interface/execution_mode/Async.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),c={name:"api/SIMD-API/basic_api/tool_interface/execution_mode/Async.md"};function t(e,s,i,d,o,r){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>Async</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_utils_intf.h&quot;</code>。</p><p>基于<a href="../../../../../guide/programming_guide/advanced_programming/hardware_implementation/basic_architecture.html">分离模式</a>（AIC和AIV分离）开发融合算子时，算子逻辑中通常同时包含AIV和AIC的处理逻辑，此时需要使用Ascend C提供的宏<code>ASCEND_IS_AIV</code>/<code>ASCEND_IS_AIC</code>实现如下硬件条件分支来对AIV和AIC的代码进行隔离：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">if</span><span class="w"> </span><span class="n">ASCEND_IS_AIV</span><span class="w"> </span><span class="p">{</span>
<span class="c1">// AIV处理逻辑</span>
<span class="p">}</span>
<span class="k">if</span><span class="w"> </span><span class="n">ASCEND_IS_AIC</span><span class="w"> </span><span class="p">{</span>
<span class="c1">// AIC处理逻辑</span>
<span class="p">}</span>
</code></pre></div><p>Async通过模板函数的方式对这种隔离模式进行了封装，提供了一个统一的接口，用于在不同执行单元（AIC或AIV）下执行特定函数，从而避免在代码中使用硬件条件分支。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">EngineType</span><span class="w"> </span><span class="n">engine</span><span class="p">,</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">funPtr</span><span class="p">,</span><span class="w"> </span><span class="k">class</span><span class="p">...</span><span class="w"> </span><span class="n">Args</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Async</span><span class="p">(</span><span class="n">Args</span><span class="p">...</span><span class="w"> </span><span class="n">args</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>engine</td><td>EngineType枚举类型，可取值如下，对应不同的硬件执行单元：<br>• AIC <br>• AIV</td></tr><tr><td>funPtr</td><td>函数指针，指定要执行的函数，函数签名和参数类型由class... Args决定。</td></tr><tr><td>class... Args</td><td>可变参数模板，表示函数参数的类型列表，用于传递给funPtr。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>Args... args</td><td>输入</td><td>与class... Args对应的参数列表，表示传递给funPtr的实际参数。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><p>无</p><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">cubeProcess</span><span class="p">(</span><span class="n">KernelMmad</span><span class="w"> </span><span class="o">&amp;</span><span class="n">op</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">A</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">B</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">c</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">InitAIC</span><span class="p">(</span><span class="n">A</span><span class="p">,</span><span class="w"> </span><span class="n">B</span><span class="p">,</span><span class="w"> </span><span class="n">c</span><span class="p">);</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">ProcessAIC</span><span class="p">();</span>
<span class="p">}</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">vectorProcess</span><span class="p">(</span><span class="n">KernelMmad</span><span class="w"> </span><span class="o">&amp;</span><span class="n">op</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">A</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">B</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">c</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">InitAIV</span><span class="p">(</span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">A</span><span class="p">,</span><span class="w"> </span><span class="n">B</span><span class="p">,</span><span class="w"> </span><span class="n">c</span><span class="p">);</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">ProcessAIV</span><span class="p">();</span>
<span class="p">}</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__mix__</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="mi">2</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">mmad_custom</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">A</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">B</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">c</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">InitSocState</span><span class="p">();</span>
<span class="w">    </span><span class="n">KernelMmad</span><span class="w"> </span><span class="n">op</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Async</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">EngineType</span><span class="o">::</span><span class="n">AIC</span><span class="p">,</span><span class="w"> </span><span class="n">cubeProcess</span><span class="o">&gt;</span><span class="p">(</span><span class="n">op</span><span class="p">,</span><span class="w"> </span><span class="n">A</span><span class="p">,</span><span class="w"> </span><span class="n">B</span><span class="p">,</span><span class="w"> </span><span class="n">c</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Async</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">EngineType</span><span class="o">::</span><span class="n">AIV</span><span class="p">,</span><span class="w"> </span><span class="n">vectorProcess</span><span class="o">&gt;</span><span class="p">(</span><span class="n">op</span><span class="p">,</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">A</span><span class="p">,</span><span class="w"> </span><span class="n">B</span><span class="p">,</span><span class="w"> </span><span class="n">c</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const _=a(c,[["render",t]]);export{h as __pageData,_ as default};
